\label{defn.rip}
The matrix $\Phi$ has the \emph{$(K,\delta)$-restricted isometry property (RIP)} if 
\begin{equation*}
(1-\delta)\|x\|^2\leq\|\Phi x\|^2\leq(1+\delta)\|x\|^2
\end{equation*}
for every $K$-sparse vector $x$.
The smallest $\delta$ for which $\Phi$ is $(K,\delta)$-RIP is the \emph{restricted isometry constant (RIC)} $\delta_K$.

\label{thm.rip use}
Suppose an $M\times N$ matrix $\Phi$ has the $(2K,\delta)$-restricted isometry property for some $\delta<\sqrt{2}-1$.
Assuming $\|z\|\leq\varepsilon$, then for every $K$-sparse vector $x\in\mathbb{R}^N$, the following reconstruction from \eqref{eq.cs eqn}:
\begin{equation*}
\tilde{x}=\arg\min\|\hat{x}\|_1\qquad\mbox{s.t. }\|y-\Phi\hat{x}\|\leq\varepsilon
\end{equation*}
satisfies $\|\tilde{x}-x\|\leq C\varepsilon$, where $C$ only depends on $\delta$.

\label{thm.welch bound}
Every $M\times N$ matrix $\Phi$ with unit-norm columns has worst-case coherence
\begin{equation*}
\mu\geq\sqrt{\frac{N-M}{M(N-1)}},
\end{equation*}
with equality if and only if $\Phi$ is an equiangular tight frame.

\label{lem:delta_min_bnd}
The smallest $\delta$ for which $\Phi$ is $(K,\delta)$-RIP is given by
\begin{equation}
\label{eq.delta min}
\delta_K
=\max_{\substack{\mathcal{K}\subseteq\{1,\ldots,N\}\\|\mathcal{K}|=K}}\|\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}-I_K\|_2,
\end{equation}
where $\Phi_\mathcal{K}$ denotes the submatrix consisting of columns of $\Phi$ indexed by $\mathcal{K}$.

For each eigenvalue $\lambda$ of a $K\times K$ matrix $A$, there is an index $i\in\{1,\ldots,K\}$ such that
\begin{equation*}
\Big|\lambda-A[i,i]\Big|\leq\sum_{\substack{j=1\\j\neq i}}^K\Big|A[i,j]\Big|.
\end{equation*}

The \emph{spark} of a matrix $\Phi$ is the size of the smallest linearly dependent subset of columns, i.e.,
\begin{equation*}
\mathrm{Spark}(\Phi)
=\min\Big\{\|x\|_0:\Phi x=0,~x\neq0\Big\}.
\end{equation*}

\label{thm.rip fingerprints}
Suppose fingerprints $\Phi=[\varphi_1\cdots\varphi_N]$ have restricted isometry constant $\delta_{2K}$. 
Then
\begin{equation} 
\label{lem:distbnd1}
\mathrm{dist}(\mathcal{G}_{K,n},\neg\mathcal{G}_{K,n})\geq\sqrt{\frac{1-\delta_{2K}}{K(K-1)}}. 
\end{equation}

Take $\mathcal{K},\mathcal{K}'\subseteq\{1,\ldots,N\}$ such that $|\mathcal{K}|,|\mathcal{K}'|\leq K$ and $n\in\mathcal{K}\setminus\mathcal{K}'$.
Then the left-hand inequality of the restricted isometry property gives
\begin{align}
\nonumber
\bigg\|\frac{1}{|\mathcal{K}|}\sum_{n\in\mathcal{K}}\varphi_n-\frac{1}{|\mathcal{K}'|}\sum_{n\in\mathcal{K}'}\varphi_n\bigg\|^2
\nonumber
&=\bigg\|\Big(\frac{1}{|\mathcal{K}|}-\frac{1}{|\mathcal{K}'|}\Big)\sum_{n\in\mathcal{K}\cap\mathcal{K}'}\varphi_n+\frac{1}{|\mathcal{K}|}\sum_{n\in\mathcal{K}\setminus\mathcal{K}'}\varphi_n-\frac{1}{|\mathcal{K}'|}\sum_{n\in\mathcal{K}'\setminus\mathcal{K}}\varphi_n\bigg\|^2\\
\nonumber
&\geq(1-\delta_{|\mathcal{K}\cup\mathcal{K}'|})\bigg(|\mathcal{K}\cap\mathcal{K}'|\Big(\frac{1}{|\mathcal{K}|}-\frac{1}{|\mathcal{K}'|}\Big)^2+\frac{|\mathcal{K}\setminus\mathcal{K}'|}{|\mathcal{K}|^2}+\frac{|\mathcal{K}'\setminus\mathcal{K}|}{|\mathcal{K}'|^2}\bigg)\\
\label{eq.distance bound}
&=\frac{1-\delta_{|\mathcal{K}\cup\mathcal{K}'|}}{|\mathcal{K}||\mathcal{K}'|}\bigg(|\mathcal{K}|+|\mathcal{K}'|-2|\mathcal{K}\cap\mathcal{K}'|\bigg).
\end{align}
For a fixed $|\mathcal{K}|$, we will find a lower bound for
\begin{equation}
\label{eq.min value} \frac{1}{|\mathcal{K}|}\bigg(|\mathcal{K}|+|\mathcal{K}'|-2|\mathcal{K}\cap\mathcal{K}'|\bigg)=1+\frac{|\mathcal{K}|-2|\mathcal{K}\cap\mathcal{K}'|}{|\mathcal{K}'|}.
\end{equation}
Since we can have $|\mathcal{K}\cap\mathcal{K}'|>\frac{|\mathcal{K}|}{2}$, 
we know $\frac{|\mathcal{K}|-2|\mathcal{K}\cap\mathcal{K}'|}{|\mathcal{K}'|}<0$ when \eqref{eq.min value} is minimized.  
That said, $|\mathcal{K}'|$ must be as small as possible, i.e., $|\mathcal{K}'|=|\mathcal{K}\cap\mathcal{K}'|$.
Thus, when \eqref{eq.min value} is minimized, we have
\begin{equation*}
\frac{1}{|\mathcal{K}|}\bigg(|\mathcal{K}|+|\mathcal{K}'|-2|\mathcal{K}\cap\mathcal{K}'|\bigg)=\frac{|\mathcal{K}|}{|\mathcal{K}\cap\mathcal{K}'|}-1,
\end{equation*}
i.e., $|\mathcal{K}\cap\mathcal{K}'|$ must be as large as possible.
Since $n\in\mathcal{K}\setminus\mathcal{K}'$, we have $|\mathcal{K}\cap\mathcal{K}'|\leq|\mathcal{K}|-1$.
Therefore,
\begin{equation}
\label{eq.min value 2}
\frac{1}{|\mathcal{K}|}\bigg(|\mathcal{K}|+|\mathcal{K}'|-2|\mathcal{K}\cap\mathcal{K}'|\bigg)\geq\frac{1}{|\mathcal{K}|-1}.
\end{equation}
Substituting \eqref{eq.min value 2} into \eqref{eq.distance bound} gives 
\begin{equation*}
\bigg\|\frac{1}{|\mathcal{K}|}\sum_{n\in\mathcal{K}}\varphi_n-\frac{1}{|\mathcal{K}'|}\sum_{n\in\mathcal{K}'}\varphi_n\bigg\|^2
\geq\frac{1-\delta_{|\mathcal{K}\cup\mathcal{K}'|}}{|\mathcal{K}|(|\mathcal{K}|-1)}
\geq\frac{1-\delta_{2K}}{K(K-1)}.
\end{equation*}
Since this bound holds for every $n$, $\mathcal{K}$ and $\mathcal{K}'$ with $n\in\mathcal{K}\setminus\mathcal{K}'$, we have~\eqref{lem:distbnd1}.

\label{cor:etf_fingerprints}
Suppose fingerprints $\Phi=[\varphi_1\cdots\varphi_N]$ are unit-norm with worst-case coherence $\mu$.  
Then
\begin{equation}
\label{eq:dm:bound_dist_guilty_notguilty_set}
\mathrm{dist}(\mathcal{G}_{K,n},\neg\mathcal{G}_{K,n})\geq\sqrt{\frac{1-(2K-1)\mu}{K(K-1)}}. 
\end{equation}

\label{thm:cq:linear_attack_against_corr_detector}
Take fingerprints as the columns of an $M\times N$ matrix $\Phi=[\varphi_1\cdots\varphi_N]$, which, when normalized by the fingerprints' common norm $\gamma$, forms an equiangular tight frame.
If the noise $z$ included in the attack \eqref{eq:dm:attack1} has independent Gaussian entries of mean zero and variance $\sigma^2$, then the worst-case type I and type II error probabilities, \eqref{eq:cq:worst_case_error_1} and \eqref{eq:cq:worst_case_error_2}, satisfy
\begin{align*}
\mathrm{P}_\mathrm{I}(\Phi,\tau,\{x_k\}_{k=1}^K)
&\leq Q\bigg(\frac{\gamma}{\sigma}\big(\tau-\mu\big)\bigg),\\
\mathrm{P}_\mathrm{II}(\Phi,\tau,\{x_k\}_{k=1}^K)
&\leq Q\bigg(\frac{\gamma}{\sigma}\Big((1+\mu)\max\{x_k\}_{k=1}^K-\mu-\tau\Big)\bigg),
\end{align*}
where $Q(x) := \frac{1}{\sqrt{2\pi}}\int_{x}^{\infty} e^{-u^2/2} du$ and $\mu=\sqrt{\frac{N-M}{M(N-1)}}$.

Suppose a Vandermonde matrix is equal norm and tight.  
Note that a zero base will produce the zeroth identity basis element $\delta_0$.
Letting $\mathcal{P}$ denote the indices of the nonzero bases, the fact that the matrix is full rank implies $|\mathcal{P}|\geq M-1$.
Also, equal norm gives that the frame element length
\[ \|\varphi_n\|^2=\sum_{m=0}^{M-1}|\varphi_n[m]|^2=\sum_{m=0}^{M-1}|\alpha_n^m|^2=\sum_{m=0}^{M-1}|\alpha_n|^{2m} \]
is constant over $n\in\mathcal{P}$.  
Since $\sum_{m=0}^{M-1}x^{2m}$ is strictly increasing over $0<x<\infty$, there exists $c>0$ such that $|\alpha_n|^2=c$ for all $n\in\mathcal{P}$.   
Next, tightness gives that the rows have equal norm, implying that the first two rows have equal norm, i.e., $|\mathcal{P}|c=|\mathcal{P}|c^2$.  
Thus $c=1$, and so the nonzero bases are in the complex unit circle.  
Furthermore, since the zeroth and first rows have equal norm by tightness, we have $|\mathcal{P}|=N$, and so every base is in the complex unit circle.

Now consider the inner product between Vandermonde frame elements whose bases $\{e^{2\pi i x_n}\}_{n=1}^N$ come from the complex unit circle:
\[ \langle \varphi_n,\varphi_{n'}\rangle=\sum_{m=0}^{M-1}(e^{2\pi i x_n})^m\overline{(e^{2\pi i x_{n'}})^m}=\sum_{m=0}^{M-1}e^{2\pi i (x_n-x_{n'})m}. \]
We will show that the worst-case coherence comes from the two closest bases.  
Consider the following function:
\begin{equation}
\label{eq.g function}
g(x)
:=\bigg|\sum_{m=0}^{M-1}e^{2\pi ixm}\bigg|^2.
\end{equation}
Figure~\ref{figure} gives a plot of this function in the case where $M=5$.
We will prove two things about this function:
\begin{itemize}
\item[(i)] $\tfrac{d}{dx}g(x)<0$ for every $x\in(0,\tfrac{1}{2M})$,
\item[(ii)] $g(x)\leq g(\tfrac{1}{2M})$ for every $x\in(\tfrac{1}{2M},1-\tfrac{1}{2M})$.
\end{itemize}

\begin{figure}[t]
\centering
\includegraphics[width=0.5\textwidth]{fullsparkfigure.pdf}
\caption{Plot of $g$ defined by \eqref{eq.g function} in the case where $M=5$.  Observe (i) that $g$ is strictly decreasing on the interval $(0,\frac{1}{10})$, and (ii) that $g(x)\leq g(\frac{1}{10})$ for every $x\in(\frac{1}{10},\frac{9}{10})$.  As established in the proof of Theorem~\ref{thm.vandermonde}, $g$ behaves in this manner for general values of $M$.
\label{figure}}
\end{figure}

First, we claim that (i) and (ii) are sufficient to prove our result.
To establish this, we first show that the two closest bases $e^{2\pi ix_{n'}}$ and $e^{2\pi ix_{n''}}$ satisfy $|x_{n'}-x_{n''}|\leq\frac{1}{2M}$.
Without loss of generality, the $n$'s are ordered in such a way that $\{x_n\}_{n=0}^{N-1}\subseteq[0,1)$ are nondecreasing.
Define
\begin{equation*}
d(x_n,x_{n+1})
:=\left\{\begin{array}{ll}
x_{n+1}-x_n,&n=0,\ldots,N-2\\ 
x_0-(x_{N-1}-1),&n=N-1,
\end{array}
\right.
\end{equation*}
and let $n'$ be the $n$ which minimizes $d(x_n,x_{n+1})$.
Since the minimum is less than the average, we have
\begin{equation}
\label{eq.average inequality}
d(x_{n'},x_{n'+1})\leq\frac{1}{N}\bigg((x_0-(x_{N-1}-1))+\sum_{n=0}^{N-1}(x_{n+1}-x_n)\bigg)=\frac{1}{N}\leq\frac{1}{2M},
\end{equation}
provided $N\geq2M$.
Note that if we view $\{x_n\}_{n\in\mathbb{Z}_N}$ as members of $\mathbb{R}/\mathbb{Z}$, then $d(x_n,x_{n+1})=x_{n+1}-x_n$.
Since $g(x)$ is even, then (i) implies that $|\langle \varphi_{n'+1},\varphi_{n'}\rangle|^2=g(x_{n'+1}-x_{n'})$ is larger than any other $g(x_p-x_{p'})=|\langle \varphi_p,\varphi_{p'}\rangle|^2$ in which $x_p-x_{p'}\in[0,\tfrac{1}{2M}]\cup[1-\tfrac{1}{2M},1)$.
Next, \eqref{eq.average inequality} and (ii) together imply that $|\langle \varphi_{n'+1},\varphi_{n'}\rangle|^2=g(x_{n'+1}-x_{n'})\geq g(\tfrac{1}{2M})$ is larger than any other $g(x_p-x_{p'})=|\langle \varphi_p,\varphi_{p'}\rangle|^2$ in which $x_p-x_{p'}\in(\tfrac{1}{2M},1-\tfrac{1}{2M})$, provided $N\geq2M$.
Combined, (i) and (ii) give that $|\langle \varphi_{n'+1},\varphi_{n'}\rangle|$ achieves the worst-case coherence of $\{\varphi_n\}_{n\in\mathbb{Z}_N}$.
Additionally, (i) gives that the worst-case coherence $|\langle \varphi_{n'+1},\varphi_{n'}\rangle|$ is minimized when $x_{n'+1}-x_{n'}$ is maximized, i.e., when the $x_n$'s are equally spaced in the unit interval.

To prove (i), note that the geometric sum formula gives
\begin{equation}
\label{eq.g of x}
g(x)
=\bigg|\sum_{m=0}^{M-1}e^{2\pi ixm}\bigg|^2
=\bigg|\frac{e^{2M\pi ix}-1}{e^{2\pi ix}-1}\bigg|^2
=\frac{2-2\cos(2M\pi x)}{2-2\cos(2\pi x)}
=\bigg(\frac{\sin(M\pi x)}{\sin(\pi x)}\bigg)^2,
\end{equation}
where the final expression uses the identity $1-\cos(2z)=2\sin^2 z$.
To show that $g$ is decreasing over $(0,\frac{1}{2M})$, note that the base of \eqref{eq.g of x} is positive on this interval, and performing the quotient rule to calculate its derivative will produce a fraction whose denominator is nonnegative and whose numerator is given by
\begin{equation}
\label{eq.g of x 2}
M\pi\sin(\pi x)\cos(M\pi x)-\pi\sin(M\pi x)\cos(\pi x).
\end{equation}
This factor is zero at $x=0$ and has derivative:
\begin{equation*}
-(M^2-1)\pi^2\sin(\pi x)\sin(M\pi x),
\end{equation*}
which is strictly negative for all $x\in(0,\tfrac{1}{2M})$.
Hence, \eqref{eq.g of x 2} is strictly negative whenever $x\in(0,\tfrac{1}{2M})$, and so $g'(x)<0$ for every $x\in(0,\tfrac{1}{2M})$.

For (ii), note that for every $x\in(\frac{1}{2M},1-\frac{1}{2M})$, we can individually bound the numerator and denominator of what the geometric sum formula gives:
\begin{equation*}
g(x)
=\bigg|\sum_{m=0}^{M-1}e^{2\pi ixm}\bigg|^2
=\frac{|e^{2M\pi ix}-1|^2}{|e^{2\pi ix}-1|^2}
\leq\frac{|e^{\pi i}-1|^2}{|e^{\pi i/M}-1|^2}
=\bigg|\sum_{m=0}^{M-1}e^{\pi im/M}\bigg|^2
=g(\tfrac{1}{2M}).\qedhere
\end{equation*}

\label{thm.closure}
Take an $N\times N$ discrete Fourier transform matrix, and select the rows indexed by $\mathcal{M}\subseteq\mathbb{Z}_N$ to build the matrix $\Phi$.
If $\Phi$ is full spark, then so is the matrix built from rows indexed by
\begin{itemize}
\item[(i)] any translation of $\mathcal{M}$,
\item[(ii)] any $A\mathcal{M}$ with $A$ relatively prime to $N$,
\item[(iii)] the complement of $\mathcal{M}$ in $\mathbb{Z}_N$.
\end{itemize}

For (i), we first define $D$ to be the $N\times N$ diagonal matrix whose diagonal entries are $\{\omega^n\}_{n=0}^{N-1}$.
Note that, since $\omega^{(m+1)n}=\omega^n\omega^{mn}$, translating the row indices $\mathcal{M}$ by $1$ corresponds to multiplying $\Phi$ on the right by $D$.
For some set $\mathcal{K}\subseteq\mathbb{Z}_N$ of size $M:=|\mathcal{M}|$, let $\Phi_\mathcal{K}$ denote the $M\times M$ submatrix of $\Phi$ whose columns are indexed by $\mathcal{K}$, and let $D_\mathcal{K}$ denote the $M\times M$ diagonal submatrix of $D$ whose diagonal entries are indexed by $\mathcal{K}$.
Then since $D_\mathcal{K}$ is unitary, we have
\begin{equation*}
|\mathrm{det}((\Phi D)_\mathcal{K})|
=|\mathrm{det}(\Phi_\mathcal{K}D_\mathcal{K})|
=|\mathrm{det}(\Phi_\mathcal{K})||\mathrm{det}(D_\mathcal{K})|
=|\mathrm{det}(\Phi_\mathcal{K})|.
\end{equation*}
Thus, if $\Phi$ is full spark, $|\mathrm{det}((\Phi D)_\mathcal{K})|=|\mathrm{det}(\Phi_\mathcal{K})|>0$, and so $\Phi D$ is also full spark.
Using this fact inductively proves (i) for all translations of $\mathcal{M}$.

For (ii), let $\Psi$ denote the submatrix of rows indexed by $A\mathcal{M}$.
Then for any $\mathcal{K}\subseteq\mathbb{Z}_N$ of size $M$,
\begin{equation*}
\mathrm{det}(\Psi_\mathcal{K})
=\mathrm{det}(\omega^{(Am)k})_{m\in\mathcal{M},k\in\mathcal{K}}
=\mathrm{det}(\omega^{m(Ak)})_{m\in\mathcal{M},k\in\mathcal{K}}
=\mathrm{det}(\Phi_{A\mathcal{K}}).
\end{equation*}
Since $A$ is relatively prime to $N$, multiplication by $A$ permutes the elements of $\mathbb{Z}_N$, and so $A\mathcal{K}$ has exactly $M$ distinct elements.
Thus, if $\Phi$ is full spark, then $\mathrm{det}(\Psi_\mathcal{K})=\mathrm{det}(\Phi_{A\mathcal{K}})\neq0$, and so $\Psi$ is also full spark.

For (iii), we let $\Psi$ be the $(N-M)\times N$ submatrix of rows indexed by $\mathcal{M}^\mathrm{c}$, so that
\begin{equation}
\label{eq.complements}
NI_N
=\begin{bmatrix}\Phi^* & \Psi^*\end{bmatrix}\begin{bmatrix}\Phi\\\Psi\end{bmatrix}
=\Phi^*\Phi+\Psi^*\Psi.
\end{equation}
We will use contraposition to show that $\Phi$ being full spark implies that $\Psi$ is also full spark.
To this end, suppose $\Psi$ is not full spark.
Then $\Psi$ has a collection of $N-M$ linearly dependent columns $\{\psi_i\}_{i\in \mathcal{K}}$, and so there exists a nontrivial sequence $\{\alpha_i\}_{i\in \mathcal{K}}$ such that 
\begin{equation*}
\sum_{i\in \mathcal{K}}\alpha_i\psi_i
=0.
\end{equation*}
Considering $\psi_i=\Psi\delta_i$, where $\delta_i$ is the $i$th identity basis element, we can use \eqref{eq.complements} to express this linear dependence in terms of $\Phi$:
\begin{equation*}
0
=\Psi^*0
=\Psi^*\sum_{i\in \mathcal{K}}\alpha_i\psi_i
=\sum_{i\in \mathcal{K}}\alpha_i\Psi^*\Psi\delta_i
=\sum_{i\in \mathcal{K}}\alpha_i(NI_N-\Phi^*\Phi)\delta_i.
\end{equation*}
Rearranging then gives
\begin{equation}
\label{eq.x defn}
x:=N\sum_{i\in \mathcal{K}}\alpha_i\delta_i=\sum_{i\in \mathcal{K}}\alpha_i\Phi^*\Phi\delta_i.
\end{equation}
Here, we note that $x$ is nonzero since $\{\alpha_i\}_{i\in \mathcal{K}}$ is nontrivial, and that $x\in\mathrm{Range}(\Phi^*\Phi)$.
Furthermore, whenever $j\not\in \mathcal{K}$, we have from \eqref{eq.x defn} that
\begin{equation*}
\langle x,\Phi^*\Phi\delta_j\rangle
=\langle \Phi^*\Phi x,\delta_j\rangle
=N\bigg\langle \Phi^*\Phi\sum_{i\in \mathcal{K}}\alpha_i\delta_i,\delta_j\bigg\rangle
=N^2\bigg\langle\sum_{i\in \mathcal{K}}\alpha_i\delta_i,\delta_j\bigg\rangle
=0,
\end{equation*}
and so $x\perp\mathrm{Span}\{\Phi^*\Phi\delta_j\}_{j\in \mathcal{K}^\mathrm{c}}$.
Thus, the containment $\mathrm{Span}\{\Phi^*\Phi\delta_j\}_{j\in \mathcal{K}^\mathrm{c}}\subseteq\mathrm{Range}(\Phi^*\Phi)$ is proper, and so
\begin{equation*}
M
=\mathrm{Rank}(\Phi)
=\mathrm{Rank}(\Phi^*\Phi)
>\mathrm{Rank}(\Phi^*\Phi_{\mathcal{K}^\mathrm{c}})
=\mathrm{Rank}(\Phi_{\mathcal{K}^\mathrm{c}}).
\end{equation*}
Since the $M\times M$ submatrix $\Phi_{\mathcal{K}^\mathrm{c}}$ is rank-deficient, it is not invertible, and therefore $\Phi$ is not full spark.

Select rows indexed by $\mathcal{M}\subseteq\mathbb{Z}_N$ from the $N\times N$ discrete Fourier transform matrix and then normalize the columns to produce the harmonic frame $\Phi$.
Then $\Phi$ satisfies the $(K,\delta)$-restricted isometry property only if
\begin{equation*}
\Big|\big|\mathcal{M}\cap(a+\langle d\rangle)\big|-\tfrac{|\mathcal{M}|}{d}\Big|\leq\tfrac{|\mathcal{M}|}{d}\delta
\end{equation*}
for every divisor $d$ of $N$ with $d\leq K$ and every $a=0,\ldots,d-1$.

\label{thm.uniformly distributed}
Let $N$ be a prime power, and select rows indexed by $\mathcal{M}\subseteq\mathbb{Z}_N$ from the $N\times N$ discrete Fourier transform matrix to build the submatrix $\Phi$.
Then $\Phi$ is full spark if and only if $\mathcal{M}$ is uniformly distributed over the divisors of $N$.

\label{lem.big fraction}
Let $N$ be a power of some prime $p$, and pick $\mathcal{M}=\{m_i\}_{i=1}^M\subseteq\mathbb{Z}_N$ such that
\begin{equation}
\label{eq.big fraction}
\frac{\displaystyle{\prod_{1\leq i<j\leq M}(m_j-m_i)}}{\displaystyle{\prod_{m=0}^{M-1}m!}}
\end{equation}
is not a multiple of $p$.
Then the rows indexed by $\mathcal{M}$ in the $N\times N$ discrete Fourier transform form a full spark frame.

We wish to show that $\mathrm{det}(\omega_n^m)_{m\in\mathcal{M},1\leq n\leq M}\neq0$ for all $M$-tuples of distinct $N$th roots of unity $\{\omega_n\}_{n=1}^M$.
Define the polynomial $D(z_1,\ldots,z_M):=\mathrm{det}(z_n^m)_{m\in\mathcal{M},1\leq n\leq M}$.
Since columns $i$ and $j$ of $(z_n^m)_{m\in\mathcal{M},1\leq n\leq M}$ are identical whenever $z_i=z_j$, we know that $D$ vanishes in each of these instances, and so we can factor:
\begin{equation*}
D(z_1,\ldots,z_M)=P(z_1,\ldots,z_M)\prod_{1\leq i<j\leq M}(z_j-z_i)
\end{equation*}
for some polynomial $P(z_1,\ldots,z_M)$ with integer coefficients.
By Lemma~\ref{lem.multiple of p}, it suffices to show that $P(1,\ldots,1)$ is not a multiple of $p$, since this implies $D(\omega_1,\ldots,\omega_M)$ is nonzero for all $M$-tuples of distinct $N$th roots of unity $\{\omega_n\}_{n=1}^M$.

To this end, we proceed by considering
\begin{equation}
\label{eq.A defn}
A:=\bigg(z_1\frac{\partial}{\partial z_1}\bigg)^0\bigg(z_2\frac{\partial}{\partial z_2}\bigg)^1\cdots\bigg(z_M\frac{\partial}{\partial z_M}\bigg)^{M-1}D(z_1,\ldots,z_M)\bigg|_{z_1=\cdots=z_M=1}.
\end{equation}
To compute $A$, we note that each application of $z_j\frac{\partial}{\partial z_j}$ produces terms according to the product rule.
For some terms, a linear factor of the form $z_j-z_i$ or $z_i-z_j$ is replaced by $z_j$ or $-z_j$, respectively.
For each the other terms, these linear factors are untouched, while another factor, such as $P(z_1,\ldots,z_M)$, is differentiated and multiplied by $z_j$.
Note that there are a total of $M(M-1)/2$ linear factors, and only $M(M-1)/2$ differentiation operators to apply.
Thus, after expanding every product rule, there will be two types of terms: terms in which every differentiation operator was applied to a linear factor, and terms which have at least one linear factor remaining untouched.
When we evaluate at $z_1=\cdots=z_M=1$, the terms with linear factors vanish, and so the only terms which remain came from applying every differentiation operator to a linear factor.
Furthermore, each of these terms before the evaluation is of the form $P(z_1,\ldots,z_M)\prod_{1\leq i<j\leq M}z_j$, and so evaluation at $z_1=\cdots=z_M=1$ produces a sum of terms of the form $P(1,\ldots,1)$; to determine the value of $A$, it remains to count these terms.
The $M-1$ copies of $z_M\frac{\partial}{\partial z_M}$ can only be applied to linear factors of the form $z_M-z_i$, of which there are $M-1$, and so there are a total of $(M-1)!$ ways to distribute these operators.
Similarly, there are $(M-2)!$ ways to distribute the $M-2$ copies of $z_{M-1}\frac{\partial}{\partial z_{M-1}}$ amongst the $M-2$ linear factors of the form $z_{M-1}-z_i$.
Continuing in this manner produces an expression for $A$:
\begin{equation}
\label{eq.first A}
A=(M-1)!(M-2)!\cdots 1!0!~P(1,\ldots,1).
\end{equation}

For an alternate expression of $A$, we substitute the definition of $D(z_1,\ldots,z_M)$ into $\eqref{eq.A defn}$.
Here, we exploit the multilinearity of the determinant and the fact that $(z_n\frac{\partial}{\partial z_n})z_n^m=mz_n^m$ to get
\begin{equation}
\label{eq.second A}
A=\mathrm{det}(m^{n-1})_{m\in\mathcal{M},1\leq n\leq M}=\prod_{1\leq i<j\leq M}(m_j-m_i),
\end{equation}
where the final equality uses the fact that $(m^{n-1})_{m\in\mathcal{M},1\leq n\leq M}$ is the transpose of a Vandermonde matrix.
Equating \eqref{eq.first A} to \eqref{eq.second A} reveals that \eqref{eq.big fraction} is an expression for $P(1,\ldots,1)$.  
Thus, by assumption, $P(1,\ldots,1)$ is not a multiple of $p$, and so we are done.

($\Leftarrow$) We will use Lemma~\ref{lem.big fraction} to demonstrate that $\Phi$ is full spark.
To apply this lemma, we need to establish that \eqref{eq.big fraction} is not a multiple of $p$, and to do this, we will show that there are as many $p$-divisors in the numerator of \eqref{eq.big fraction} as there are in the denominator.
We start by counting the $p$-divisors of the denominator:
\begin{equation}
\label{eq.denominator 1}
\prod_{m=0}^{M-1}m!=\prod_{m=1}^{M-1}\prod_{\ell=1}^m \ell=\prod_{\ell=1}^{M-1}\prod_{m=1}^{M-l} \ell.
\end{equation}
For each pair of integers $k,a\geq 1$, there are $\max\{M-ap^k,~0\}$ factors in \eqref{eq.denominator 1} of the form $\ell=ap^k$.
By adding these, we count each factor $\ell$ as many times as it can be expressed as a multiple of a power of $p$, which equals the number of $p$-divisors in $\ell$.
Thus, the number of $p$-divisors of \eqref{eq.denominator 1} is
\begin{equation}
\label{eq.denominator 2}
\sum_{k=1}^{\lfloor \log_p M\rfloor}\sum_{a=1}^{\lfloor \frac{M}{p^k}\rfloor}(M-ap^k).
\end{equation}

Next, we count the $p$-divisors of the numerator of \eqref{eq.big fraction}.
To do this, we use the fact that $\mathcal{M}$ is uniformly distributed over the divisors of $N$. 
Since $N$ is a power of $p$, the only divisors of $N$ are smaller powers of $p$.
Also, the cosets of $\langle p^k\rangle$ partition $\mathcal{M}$ into subsets $S_{k,b}:=\{m_i\equiv b\mod p^k\}$.
We note that $m_j-m_i$ is a multiple of $p^k$ precisely when $m_i$ and $m_j$ belong to the same subset $S_{k,b}$ for some $0\leq b<p^k$.
To count $p$-divisors, we again count each factor $m_j-m_i$ as many times as it can be expressed as a multiple of a prime power:
\begin{equation}
\label{eq.numerator 1}
\sum_{k=1}^{\lfloor \log_p M\rfloor}\sum_{b=0}^{p^k-1}\binom{|S_{k,b}|}{2}.
\end{equation}
Write $M=qp^k+r$ with $0\leq r<p^k$.
Then $q=\lfloor\frac{M}{p^k}\rfloor$.
Since $\mathcal{M}$ is uniformly distributed over $p^k$, there are $r$ subsets $S_{k,b}$ with $q+1$ elements and $p^k-r$ subsets with $q$ elements.
We use this to get
\begin{equation*}
\sum_{b=0}^{p^k-1}\binom{|S_{k,b}|}{2}
=\binom{q+1}{2}r+\binom{q}{2}(p^k-r)
=\frac{q}{2}\Big((q-1)p^k+2r+(qp^k-qp^k)\Big).
\end{equation*}
Rearranging and substituting $M=qp^k+r$ then gives
\begin{equation*}
\sum_{b=0}^{p^k-1}\binom{|S_{k,b}|}{2}
=\frac{q}{2}\Big(2M-(q+1)p^k\Big)
=Mq-\binom{q+1}{2}p^k
=\sum_{a=1}^{\lfloor \frac{M}{p^k}\rfloor}(M-ap^k).
\end{equation*}
Thus, there are as many $p$-divisors in the numerator \eqref{eq.numerator 1} as there are in the denominator \eqref{eq.denominator 2}, and so \eqref{eq.big fraction} is not divisible by $p$.
Lemma~\ref{lem.big fraction} therefore gives that $\Phi$ is full spark.

($\Rightarrow$)
We will prove that this direction holds regardless of whether $N$ is a prime power.
Suppose $\mathcal{M}\subseteq\mathbb{Z}_N$ is not uniformly distributed over the divisors of $N$.
Then there exists a divisor $d$ of $N$ such that one of the cosets of $\langle d\rangle$ intersects $\mathcal{M}$ with $\leq\lfloor \frac{M}{d}\rfloor-1$ or $\geq\lceil\frac{M}{d}\rceil+1$ indices.
Notice that if a coset of $\langle d\rangle$ intersects $\mathcal{M}$ with $\leq\lfloor \frac{M}{d}\rfloor-1$ indices, then the complement $\mathcal{M}^\mathrm{c}$ intersects the same coset with $\geq\lceil\frac{N-M}{d}\rceil+1=\lceil\frac{|\mathcal{M}^\mathrm{c}|}{d}\rceil+1$ indices.
By Theorem~\ref{thm.closure}(iii), $\mathcal{M}$ produces a full spark harmonic frame precisely when $\mathcal{M}^\mathrm{c}$ produces a full spark harmonic frame, and so we may assume without loss of generality that there exists a coset of $\langle d\rangle$ which intersects $\mathcal{M}$ with $\geq\lceil\frac{M}{d}\rceil+1$ indices.

To prove that the rows with indices in $\mathcal{M}$ are not full spark, we find column entries which produce a singular submatrix.
Writing $M=qd+r$ with $0\leq r<d$, let $\mathcal{K}$ contain $q=\lfloor\frac{M}{d}\rfloor$ cosets of $\langle\frac{N}{d}\rangle$ along with $r$ elements from an additional coset.
We claim that the DFT submatrix with row entries $\mathcal{M}$ and column entries $\mathcal{K}$ is singular.
To see this, shuffle the rows and columns to form a matrix $A$ in which the row entries are grouped into common cosets of $\langle d\rangle$ and the column entries are grouped into common cosets of $\langle\frac{N}{d}\rangle$.
This breaks $A$ into rank-1 submatrices: each pair of cosets $a+\langle d\rangle$ and $b+\langle\frac{N}{d}\rangle$ produces a submatrix
\begin{equation*}
(\omega^{(a+id)(b+j\frac{N}{d})})_{i\in\mathcal{I},j\in\mathcal{J}}
=\omega^{ab}(\omega^{bdi}\omega^{a\frac{N}{d}j})_{i\in\mathcal{I},j\in\mathcal{J}}
\end{equation*}
for some index sets $\mathcal{I}$ and $\mathcal{J}$; this is a rank-1 outer product.
Let $\mathcal{L}$ be the largest intersection between $\mathcal{M}$ and a coset of $\langle d\rangle$.
Then $|\mathcal{L}|\geq\lceil\frac{M}{d}\rceil+1$ is the number of rows in the tallest of these rank-1 submatrices.
Define $A_\mathcal{L}$ to be the $M\times M$ matrix with entries $A_\mathcal{L}[i,j]=A[i,j]$ whenever $i\in\mathcal{L}$ and zero otherwise.
Then 
\begin{equation}
\label{eq.rank 1}
\mathrm{Rank}(A)
=\mathrm{Rank}(A_\mathcal{L}+A-A_\mathcal{L})
\leq\mathrm{Rank}(A_\mathcal{L})+\mathrm{Rank}(A-A_\mathcal{L}).
\end{equation}
Since $A-A_\mathcal{L}$ has $|\mathcal{L}|$ rows of zero entries, we also have
\begin{equation}
\label{eq.rank 2}
\mathrm{Rank}(A-A_\mathcal{L})
\leq M-|\mathcal{L}|\leq M-(\lceil\tfrac{M}{d}\rceil+1).
\end{equation}
Moreover, since we can decompose $A_\mathcal{L}$ into a sum of $\lceil\frac{M}{d}\rceil$ zero-padded rank-1 submatrices, we have $\mathrm{Rank}(A_\mathcal{L})
\leq \lceil\frac{M}{d}\rceil$.
Combining this with \eqref{eq.rank 1} and \eqref{eq.rank 2} then gives that $\mathrm{Rank}(A)\leq M-1$, and so the DFT submatrix is not invertible.

\label{defn.ro}
The matrix $\Phi$ has \emph{$(K,\theta)$-restricted orthogonality (RO)} if 
\begin{equation*}
|\langle \Phi x, \Phi y\rangle|
\leq\theta\|x\|\|y\|
\end{equation*}
for every pair of $K$-sparse vectors $x,y$ with disjoint support.
The smallest $\theta$ for which $\Phi$ has $(K,\theta)$-RO is the \emph{restricted orthogonality constant (ROC)} $\theta_K$.

$\theta_K
\leq \delta_{2K}
\leq \theta_K+\delta_K$.

\label{lem.ro to ri}
$\delta_{2K}
\leq 2\theta_K+\delta_1$.

Given a matrix $\Phi=[\varphi_1\cdots\varphi_N]$, we want to upper-bound the smallest $\delta$ for which $(1-\delta)\|x\|^2\leq\|\Phi x\|^2\leq(1+\delta)\|x\|^2$, or equivalently:
\begin{equation}
\label{eq.smallest delta}
\delta\geq\Big|\|\Phi\tfrac{x}{\|x\|}\|^2-1\Big|
\end{equation}
for every nonzero $2K$-sparse vector $x$.
We observe from \eqref{eq.smallest delta} that we may take $x$ to have unit norm without loss of generality.
Letting $\mathcal{K}$ denote a size-$2K$ set that contains the support of $x$, and letting $\{x_k\}_{k\in\mathcal{K}}$ denote the corresponding entries of $x$, the triangle inequality gives
\begin{align}
\nonumber
\Big|\|\Phi x\|^2-1\Big|
&=\bigg|\bigg\langle\sum_{i\in\mathcal{K}}x_i\varphi_i,\sum_{j\in\mathcal{K}}x_j\varphi_j\bigg\rangle-1\bigg|\\
\nonumber
&=\bigg|\sum_{i\in\mathcal{K}}\sum_{\substack{j\in\mathcal{K}\\j\neq i}}\langle x_i\varphi_i,x_j\varphi_j\rangle+\sum_{i\in\mathcal{K}}\|x_i\varphi_i\|^2-1\bigg|\\
\label{eq.smallest delta 2}
&\leq\bigg|\sum_{i\in\mathcal{K}}\sum_{\substack{j\in\mathcal{K}\\j\neq i}}\langle x_i\varphi_i,x_j\varphi_j\rangle\bigg|+\bigg|\sum_{i\in\mathcal{K}}\|x_i\varphi_i\|^2-1\bigg|.
\end{align}
Since $\sum_{i\in\mathcal{K}}|x_i|^2=1$, the second term of \eqref{eq.smallest delta 2} satisfies
\begin{equation}
\label{eq.smallest delta 3}
\bigg|\sum_{i\in\mathcal{K}}\|x_i\varphi_i\|^2-1\bigg|
\leq\sum_{i\in\mathcal{K}}|x_i|^2\Big|\|\varphi_i\|^2-1\Big|
\leq\sum_{i\in\mathcal{K}}|x_i|^2\delta_1
=\delta_1,
\end{equation}
and so it remains to bound the first term of \eqref{eq.smallest delta 2}.
To this end, we note that for each $i,j\in\mathcal{K}$ with $j\neq i$, the term $\langle x_i\varphi_i,x_j\varphi_j\rangle$ appears in
\begin{equation*}
\sum_{\substack{\mathcal{I}\subseteq\mathcal{K}\\|\mathcal{I}|=K}}\sum_{i\in\mathcal{I}}\sum_{j\in\mathcal{K}\setminus\mathcal{I}}\langle x_i\varphi_i,x_j\varphi_j\rangle
\end{equation*}
as many times as there are size-$K$ subsets of $\mathcal{K}$ which contain $i$ but not $j$, i.e., $\binom{2K-2}{K-1}$ times.
Thus, we use the triangle inequality and the definition of restricted orthogonality to get
\begin{align*}
\bigg|\sum_{i\in\mathcal{K}}\sum_{\substack{j\in\mathcal{K}\\j\neq i}}\langle x_i\varphi_i,x_j\varphi_j\rangle\bigg|
&=\bigg|\frac{1}{\binom{2K-2}{K-1}}\sum_{\substack{\mathcal{I}\subseteq\mathcal{K}\\|\mathcal{I}|=K}}\sum_{i\in\mathcal{I}}\sum_{j\in\mathcal{K}\setminus\mathcal{I}}\langle x_i\varphi_i,x_j\varphi_j\rangle\bigg|\\
&\leq\frac{1}{\binom{2K-2}{K-1}}\sum_{\substack{\mathcal{I}\subseteq\mathcal{K}\\|\mathcal{I}|=K}}\bigg|\bigg\langle \sum_{i\in\mathcal{I}}x_i\varphi_i,\sum_{j\in\mathcal{K}\setminus\mathcal{I}}x_j\varphi_j\bigg\rangle\bigg|\\
&\leq\frac{1}{\binom{2K-2}{K-1}}\sum_{\substack{\mathcal{I}\subseteq\mathcal{K}\\|\mathcal{I}|=K}}
\theta_K\bigg(\sum_{i\in\mathcal{I}}|x_i|^2\bigg)^{1/2}\bigg(\sum_{j\in\mathcal{K}\setminus\mathcal{I}}|x_j|^2\bigg)^{1/2}.
\end{align*}
At this point, $x$ having unit norm implies $(\sum_{i\in\mathcal{I}}|x_i|^2)^{1/2}(\sum_{j\in\mathcal{K}\setminus\mathcal{I}}|x_j|^2)^{1/2}\leq\frac{1}{2}$, and so
\begin{equation*}
\bigg|\sum_{i\in\mathcal{K}}\sum_{\substack{j\in\mathcal{K}\\j\neq i}}\langle x_i\varphi_i,x_j\varphi_j\rangle\bigg|
\leq\frac{1}{\binom{2K-2}{K-1}}\sum_{\substack{\mathcal{I}\subseteq\mathcal{K}\\|\mathcal{I}|=K}}
\frac{\theta_K}{2}
=\frac{\binom{2K}{K}}{\binom{2K-2}{K-1}}\frac{\theta_K}{2}
=\bigg(4-\frac{2}{K}\bigg)\frac{\theta_K}{2}.
\end{equation*}
Applying both this and \eqref{eq.smallest delta 3} to \eqref{eq.smallest delta 2} gives the result.

The matrix $\Phi=[\varphi_1\cdots\varphi_N]$ has \emph{$(K,\hat\theta)$-flat restricted orthogonality} if 
\begin{equation*}
\bigg|\bigg\langle \sum_{i\in\mathcal{I}}\varphi_i,\sum_{j\in\mathcal{J}}\varphi_j \bigg\rangle\bigg|
\leq\hat\theta(|\mathcal{I}||\mathcal{J}|)^{1/2}
\end{equation*}
for every disjoint pair of subsets $\mathcal{I},\mathcal{J}\subseteq\{1,\ldots,N\}$ with $|\mathcal{I}|,|\mathcal{J}|\leq K$.

\label{thm.fro to rip}
Construct an $M\times N$ matrix $\Phi$ by drawing each of its entries independently from a Gaussian distribution with mean zero and variance $\frac{1}{M}$, take $C$ to be the constant from Theorem~\ref{thm.fro}, and set $\alpha=0.01$.
Then $\Phi$ has $(K,\frac{(1-\alpha)\delta}{2C\log K})$-flat restricted orthogonality and $\delta_1\leq \alpha\delta$, and therefore the $(2K,\delta)$-restricted isometry property, with high probability provided $M\geq\frac{33C^2}{\delta^2}K\log^2 K\log N$.

\label{thm.bernstein}
Let $\{Z_m\}_{m=1}^M$ be independent random variables of mean zero with bounded moments, and suppose there exists $L>0$ such that
\begin{equation}
\label{eq.bernstein requirement}
\mathbb{E}|Z_m|^k
\leq\frac{\mathbb{E}|Z_m|^2}{2}L^{k-2}k!
\end{equation}
for every $k\geq2$.
Then 
\begin{equation}
\label{eq.bernstein conclusion}
\mathrm{Pr}\bigg[\sum_{m=1}^M Z_m\geq2t\bigg(\sum_{m=1}^M\mathbb{E}|Z_m|^2\bigg)^{1/2}\bigg]
\leq e^{-t^2}
\end{equation}
provided $\displaystyle{t\leq\frac{1}{2L}\bigg(\sum_{m=1}^M\mathbb{E}|Z_m|^2\bigg)^{1/2}}$.

Considering Lemma~\ref{lem.ro to ri}, it suffices to show that $\Phi$ has restricted orthogonality and that $\delta_1$ is sufficiently small.
First, to demonstrate restricted orthogonality, it suffices to demonstrate FRO by Theorem~\ref{thm.fro}, and so we will ensure that the following quantity is small:
\begin{equation}
\label{eq.we want small}
\bigg\langle\sum_{i\in\mathcal{I}}\varphi_i,\sum_{j\in\mathcal{J}}\varphi_j\bigg\rangle
=\sum_{m=1}^M\bigg(\sum_{i\in\mathcal{I}}\varphi_i[m]\bigg)\bigg(\sum_{j\in\mathcal{J}}\varphi_j[m]\bigg).
\end{equation}
Notice that $X_m:=\sum_{i\in\mathcal{I}}\varphi_i[m]$ and $Y_m:=\sum_{j\in\mathcal{J}}\varphi_j[m]$ are mutually independent over all $m=1,\ldots,M$ since $\mathcal{I}$ and $\mathcal{J}$ are disjoint.
Also, $X_m$ is Gaussian with mean zero and variance $\frac{|\mathcal{I}|}{M}$, while $Y_m$ similarly has mean zero and variance $\frac{|\mathcal{J}|}{M}$.
Viewed this way, \eqref{eq.we want small} being small corresponds to the sum of independent random variables $Z_m:=X_mY_m$ having its probability measure concentrated at zero.
To this end, Theorem~\ref{thm.bernstein} is naturally applicable, as the absolute central moments of a Gaussian random variable $X$ with mean zero and variance $\sigma^2$ are well known:
\begin{equation*}
\mathbb{E}|X|^k
=\left\{\begin{array}{rl}\sqrt{\frac{2}{\pi}}\sigma^k(k-1)!!&\mbox{ if $k$ odd},\\\sigma^k(k-1)!!&\mbox{ if $k$ even}.\end{array}\right.
\end{equation*}
Since $Z_m=X_mY_m$ is a product of independent Gaussian random variables, this gives
\begin{equation*}
\mathbb{E}|Z_m|^k
=\mathbb{E}|X_m|^k~\mathbb{E}|Y_m|^k
\leq \Big(\frac{|\mathcal{I}|}{M}\Big)^{k/2}\Big(\frac{|\mathcal{J}|}{M}\Big)^{k/2}\Big((k-1)!!\Big)^2
\leq \bigg(\frac{(|\mathcal{I}||\mathcal{J}|)^{1/2}}{M}\bigg)^kk!.
\end{equation*}
Further since $\mathbb{E}|Z_m|^2=\frac{|\mathcal{I}||\mathcal{J}|}{M^2}$, we may define $L:=2\frac{(|\mathcal{I}||\mathcal{J}|)^{1/2}}{M}$ to get \eqref{eq.bernstein requirement}.
Later, we will take $\hat\theta<\delta<\sqrt{2}-1<\frac{1}{2}$.
Considering
\begin{equation*}
t
:=\frac{\hat{\theta}\sqrt{M}}{2}
<\frac{\sqrt{M}}{4}
=\frac{1}{2L}\Big(M\frac{|\mathcal{I}||\mathcal{J}|}{M^2}\Big)^{1/2}
=\frac{1}{2L}\bigg(\sum_{m=1}^M\mathbb{E}|Z_m|^2\bigg)^{1/2},
\end{equation*}
we therefore have \eqref{eq.bernstein conclusion}, which in this case has the form
\begin{equation*}
\mathrm{Pr}\Bigg[\bigg|\bigg\langle\sum_{i\in\mathcal{I}}\varphi_i,\sum_{j\in\mathcal{J}}\varphi_j\bigg\rangle\bigg|\geq\hat{\theta}(|\mathcal{I}||\mathcal{J}|)^{1/2}\Bigg]
\leq 2e^{-M\hat{\theta}^2/4},
\end{equation*}
where the probability is doubled due to the symmetric distribution of $\sum_{m=1}^M Z_m$.
Since we need to account for all possible choices of $\mathcal{I}$ and $\mathcal{J}$, we will perform a union bound.
The total number of choices is given by
\begin{equation*}
\sum_{|\mathcal{I}|=1}^K\sum_{|\mathcal{J}|=1}^K\binom{N}{|\mathcal{I}|}\binom{N-|\mathcal{I}|}{|\mathcal{J}|}
\leq K^2\binom{N}{K}^2
\leq N^{2K},
\end{equation*}
and so the union bound gives
\begin{equation}
\label{eq.probability bound 1}
\mathrm{Pr}\Big[\mbox{$\Phi$ does not have $(K,\hat{\theta})$-FRO}\Big]
\leq 2e^{-M\hat{\theta}^2/4}~N^{2K}
=2\exp\Big(-\frac{M\hat{\theta}^2}{4}+2K\log N\Big).
\end{equation}
Thus, Gaussian matrices tend to have FRO, and hence restricted orthogonality by Theorem~\ref{thm.fro}; this is made more precise below.

Again by Lemma~\ref{lem.ro to ri}, it remains to show that $\delta_1$ is sufficiently small.
To this end, we note that $M\|\varphi_n\|^2$ has chi-squared distribution with $M$ degrees of freedom, and so we can use another (simpler) concentration-of-measure result; see Lemma 1 of~\cite{LaurentM:00}:
\begin{equation*}
\mathrm{Pr}\bigg[\Big|\|\varphi_n\|^2-1\Big|\geq 2\Big(\sqrt{\frac{t}{M}}+\frac{t}{M}\Big)\bigg]\leq 2e^{-t}
\end{equation*}
for any $t>0$.
Specifically, we pick
\begin{equation*}
\delta'
:=2\Big(\sqrt{\frac{t}{M}}+\frac{t}{M}\Big)
\leq\frac{4t}{M},
\end{equation*}
and we perform a union bound over the $N$ choices for $\varphi_n$:
\begin{equation}
\label{eq.probability bound 2}
\mathrm{Pr}\Big[\delta_1>\delta'\Big]
\leq 2\exp\Big(-\frac{M\delta'}{4}+\log N\Big).
\end{equation}
To summarize, Lemma~\ref{lem.ro to ri}, the union bound, Theorem~\ref{thm.fro}, and \eqref{eq.probability bound 1} and \eqref{eq.probability bound 2} give
\begin{align*}
\mathrm{Pr}\Big[\delta_{2K}>\delta\Big]
&\leq\mathrm{Pr}\Big[\theta_K>\frac{(1-\alpha)\delta}{2}\mbox{ or }\delta_1>\alpha\delta\Big]\\
&\leq\mathrm{Pr}\Big[\theta_K>\frac{(1-\alpha)\delta}{2}\Big]+\mathrm{Pr}\Big[\delta_1>\alpha\delta\Big]\\
&\leq\mathrm{Pr}\Big[\mbox{$\Phi$ does not have $\displaystyle{\Big(K,\frac{(1-\alpha)\delta}{2C\log K}\Big)}$-FRO}\Big]+\mathrm{Pr}\Big[\delta_1>\alpha\delta\Big]\\
&\leq2\exp\Big(-\frac{M}{4}\Big(\frac{(1-\alpha)\delta}{2C\log K}\Big)^2+2K\log N\Big)+2\exp\Big(-\frac{M\alpha\delta}{4}+\log N\Big),
\end{align*}
and so $M\geq\frac{33C^2}{\delta^2}K\log^2 K\log N$ gives that $\Phi$ has $(2K,\delta)$-RIP with high probability.

\label{thm.power to rip}
Construct an $M\times N$ matrix $\Phi$ by drawing each of its entries independently from a Gaussian distribution with mean zero and variance $\frac{1}{M}$, and take $\delta_{K;q}$ to be as defined in Theorem~\ref{thm.power method defn}.
Then $\delta_{K;q}\leq\delta$, and therefore $\Phi$ has the $(K,\delta)$-restricted isometry property, with high probability provided $M\geq\frac{81}{\delta^2}K^{1+1/q}\log\frac{eN}{K}$.

Take $t:=\frac{\delta}{3K^{1/2q}}-(\frac{K}{M})^{1/2}$ and pick $\mathcal{K}\subseteq\{1,\ldots,N\}$.
Then Theorem~II.13 of~\cite{DavidsonS:01} states
\begin{equation*}
\mathrm{Pr}\bigg[1-\bigg(\sqrt{\frac{K}{M}}+t\bigg)\leq\sigma_{\min}(\Phi_\mathcal{K})\leq\sigma_{\max}(\Phi_\mathcal{K})\leq1+\bigg(\sqrt{\frac{K}{M}}+t\bigg)\bigg]
\geq 1-2e^{-Mt^2/2}.
\end{equation*}
Continuing, we use the fact that $\lambda(\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{})=\sigma(\Phi_\mathcal{K})^2$ to get
\begin{align}
\nonumber
&1-2e^{-Mt^2/2}\\
\nonumber
&\leq \mathrm{Pr}\bigg[\bigg(1-\bigg(\sqrt{\frac{K}{M}}+t\bigg)\bigg)^2\leq\lambda_{\min}(\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{})\leq\lambda_{\max}(\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{})\leq\bigg(1+\bigg(\sqrt{\frac{K}{M}}+t\bigg)\bigg)^2\bigg]\\
\label{eq.eigenvalue interval}
&\leq \mathrm{Pr}\bigg[1-3\bigg(\sqrt{\frac{K}{M}}+t\bigg)\leq\lambda_{\min}(\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{})\leq\lambda_{\max}(\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{})\leq1+3\bigg(\sqrt{\frac{K}{M}}+t\bigg)\bigg],
\end{align}
where the last inequality follows from the fact that $(\frac{K}{M})^{1/2}+t<1$.
Since $\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}$ and $I_K$ are simultaneously diagonalizable, the spectrum of $\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}-I_K$ is given by $\lambda(\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}-I_K)=\lambda(\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{})-1$.
Combining this with \eqref{eq.eigenvalue interval} then gives
\begin{equation*}
\mathrm{Pr}\bigg[\Big\|\lambda(\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}-I_K)\Big\|_\infty\leq 3\bigg(\sqrt{\frac{K}{M}}+t\bigg)\bigg]
\geq 1-2e^{-Mt^2/2}.
\end{equation*}
Considering $\mathrm{Tr}[A^{2q}]^\frac{1}{2q}=\|\lambda(A)\|_{2q}\leq K^\frac{1}{2q}\|\lambda(A)\|_\infty$, we continue:
\begin{equation*}
\mathrm{Pr}\bigg[\mathrm{Tr}[(\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}-I_K)^{2q}]^\frac{1}{2q}\leq \delta \bigg]
\geq \mathrm{Pr}\bigg[ K^\frac{1}{2q}\Big\|\lambda(\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}-I_K)\Big\|_\infty \leq \delta \bigg]
\geq 1-2e^{-Mt^2/2}.
\end{equation*}
From here, we perform a union bound over all possible choices of $\mathcal{K}$:
\begin{align}
\nonumber
\mathrm{Pr}\bigg[\exists\mathcal{K}\mbox{ s.t. }\mathrm{Tr}[(\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}-I_K)^{2q}]^\frac{1}{2q}> \delta\bigg]
&\leq\binom{N}{K}\mathrm{Pr}\bigg[\mathrm{Tr}[(\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}-I_K)^{2q}]^\frac{1}{2q}> \delta \bigg]\\
\label{eq.whp 1}
&\leq2\exp\Big(-\frac{Mt^2}{2}+K\log \frac{eN}{K}\Big).
\end{align}
Rearranging $M\geq\frac{81}{\delta^2}K^{1+1/q}\log\frac{eN}{K}$ gives $K^{1/2}\leq\frac{\delta M^{1/2}}{9K^{1/2q}\log^{1/2}(eN/K)}\leq\frac{\delta M^{1/2}}{9K^{1/2q}}$, and so
\begin{equation}
\label{eq.whp 2}
\frac{Mt^2}{2}
=\frac{1}{2}\bigg(\frac{\delta M^{1/2}}{3K^{1/2q}}-K^{1/2}\bigg)^2
\geq\frac{1}{2}\bigg(\frac{2\delta M^{1/2}}{9K^{1/2q}}\bigg)^2
\geq 2K\log\frac{eN}{K}.
\end{equation}
Combining \eqref{eq.whp 1} and \eqref{eq.whp 2} gives the result.

\label{thm.etf to srg}
Every real $M\times N$ equiangular tight frame with $N>M+1$ is flipping equivalent to a frame whose Seidel adjacency matrix corresponds to the join of a vertex with a strongly regular graph of the form
\begin{equation*}
\mathrm{srg}\bigg(N-1,L,\frac{3L-N}{2},\frac{L}{2}\bigg),
\qquad L:=\frac{N}{2}-1+\bigg(1-\frac{N}{2M}\bigg)\sqrt{\frac{M(N-1)}{N-M}}.
\end{equation*}
Conversely, every such graph corresponds to flipping equivalence classes of equiangular tight frames in the same manner.

\label{thm.etf clique}
Take a real equiangular tight frame $\Phi$ with worst-case coherence $\mu$, and let $G$ denote the corresponding strongly regular graph in Theorem~\ref{thm.etf to srg}.
Then the restricted isometry constant of $\Phi$ is given by $\delta_K=(K-1)\mu$ for every $K\leq\omega(G)+1$, where $\omega(G)$ denotes the size of the largest clique in $G$.

Given a $d$-regular graph of $n$ vertices, the second largest eigenvalue $\lambda$ of its adjacency matrix satisfies
\begin{equation*}
\bigg|E(\mathcal{I},\mathcal{J})-\frac{d}{n}|\mathcal{I}||\mathcal{J}|\bigg|
\leq \lambda(|\mathcal{I}||\mathcal{J}|)^{1/2}
\end{equation*}
for every pair of vertex subsets $\mathcal{I}, \mathcal{J}$.

\label{thm.clique upper bound}
Let $G$ denote the Paley graph of prime order $p$.
Then the size of the largest clique is $\omega(G)<\sqrt{p}$.

We start by showing $\omega(G)+1\leq M$.
Suppose otherwise: that there exists a clique $\mathcal{K}$ of size $M+1$ in the join of a vertex with $G$.
Then the corresponding sub-Gram matrix of the Paley ETF has the form $\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}=(1+\mu)I_{M+1}-\mu J_{M+1}$, where $\mu=p^{-1/2}$ is the worst-case coherence and $J_{M+1}$ is the $(M+1)\times (M+1)$ matrix of 1's.
Since the largest eigenvalue of $J_{M+1}$ is $M+1$, the smallest eigenvalue of $\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}$ is $1+p^{-1/2}-(M+1)p^{-1/2}=1-\frac{1}{2}(p+1)p^{-1/2}$, which is negative when $p\geq 5$, contradicting the fact that $\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}$ is positive semidefinite.

Since $\omega(G)+1\leq M$, we can apply Lemma~\ref{lem.paley ric} and Theorem~\ref{thm.etf clique} to get
\begin{equation}
\label{eq.clique vs 1}
1>\delta_{\omega(G)+1}=\Big(\omega(G)+1-1\Big)\mu=\frac{\omega(G)}{\sqrt{p}},
\end{equation}
and rearranging gives the result.

Given arbitrary disjoint subsets $\mathcal{I},\mathcal{J}\subseteq\{1,\ldots,N\}$ with $|\mathcal{I}|,|\mathcal{J}|\leq K$, we will bound the following quantity three times, each time with different constraints on $\{x_i\}_{i\in\mathcal{I}}$ and $\{y_j\}_{j\in\mathcal{J}}$:
\begin{equation}
\label{eq.to bound}
\bigg|\bigg\langle \sum_{i\in\mathcal{I}}x_i\varphi_i,\sum_{j\in\mathcal{J}}y_j\varphi_j \bigg\rangle\bigg|.
\end{equation}
To be clear, our third bound will have no constraints on $\{x_i\}_{i\in\mathcal{I}}$ and $\{y_j\}_{j\in\mathcal{J}}$, thereby demonstrating restricted orthogonality.
Note that by assumption, \eqref{eq.to bound} is $\leq\hat\theta(|\mathcal{I}||\mathcal{J}|)^{1/2}$ whenever the $x_i$'s and $y_j$'s are in $\{0,1\}$.
We first show that this bound is preserved when we relax the $x_i$'s and $y_j$'s to lie in the interval $[0,1]$.

Pick a disjoint pair of subsets $\mathcal{I}',\mathcal{J}'\subseteq\{1,\ldots,N\}$ with $|\mathcal{I}'|,|\mathcal{J}'|\leq K$.
Starting with some $k\in\mathcal{I}'$, note that flat restricted orthogonality gives that
\begin{align*}
\bigg|\bigg\langle \sum_{i\in\mathcal{I}}\varphi_i,\sum_{j\in\mathcal{J}}\varphi_j \bigg\rangle\bigg|
&\leq\hat\theta(|\mathcal{I}||\mathcal{J}|)^{1/2},\\
\bigg|\bigg\langle \sum_{i\in\mathcal{I}\setminus\{k\}}\varphi_i,\sum_{j\in\mathcal{J}}\varphi_j \bigg\rangle\bigg|
&\leq\hat\theta(|\mathcal{I}\setminus\{k\}||\mathcal{J}|)^{1/2}
\leq\hat\theta(|\mathcal{I}||\mathcal{J}|)^{1/2}
\end{align*}
for every disjoint $\mathcal{I},\mathcal{J}\subseteq\{1,\ldots,N\}$ with $|\mathcal{I}|,|\mathcal{J}|\leq K$ and $k\in\mathcal{I}$.
Thus, we may take any $x_k\in[0,1]$ to form a convex combination of these two expressions, and then the triangle inequality gives
\begin{align}
\nonumber
\hat\theta(|\mathcal{I}||\mathcal{J}|)^{1/2}
&\geq x_k\bigg|\bigg\langle \sum_{i\in\mathcal{I}}\varphi_i,\sum_{j\in\mathcal{J}}\varphi_j \bigg\rangle\bigg|+(1-x_k)\bigg|\bigg\langle \sum_{i\in\mathcal{I}\setminus\{k\}}\varphi_i,\sum_{j\in\mathcal{J}}\varphi_j \bigg\rangle\bigg|\\
\nonumber
&\geq\bigg|x_k\bigg\langle \sum_{i\in\mathcal{I}}\varphi_i,\sum_{j\in\mathcal{J}}\varphi_j \bigg\rangle+(1-x_k)\bigg\langle \sum_{i\in\mathcal{I}\setminus\{k\}}\varphi_i,\sum_{j\in\mathcal{J}}\varphi_j \bigg\rangle\bigg|\\
\label{eq.convex trick}
&=\bigg|\bigg\langle \sum_{i\in\mathcal{I}}\bigg\{\begin{array}{cc}x_k,&i=k\\1,&i\neq k\end{array}\bigg\}\varphi_i,\sum_{j\in\mathcal{J}}\varphi_j \bigg\rangle\bigg|.
\end{align}
Since \eqref{eq.convex trick} holds for every disjoint $\mathcal{I},\mathcal{J}\subseteq\{1,\ldots,N\}$ with $|\mathcal{I}|,|\mathcal{J}|\leq K$ and $k\in\mathcal{I}$, we can do the same thing with an additional index $i\in\mathcal{I}'$ or $j\in\mathcal{J}'$, and replace the corresponding unit coefficient with some $x_i$ or $y_j$ in $[0,1]$.
Continuing in this way proves the claim that \eqref{eq.to bound} is $\leq\hat\theta(|\mathcal{I}||\mathcal{J}|)^{1/2}$ whenever the $x_i$'s and $y_j$'s lie in the interval $[0,1]$.

For the second bound, we assume the $x_i$'s and $y_j$'s are nonnegative with unit norm: $\sum_{i\in\mathcal{I}}x_i^2=\sum_{j\in\mathcal{J}}y_j^2=1$.
To bound \eqref{eq.to bound} in this case, we partition $\mathcal{I}$ and $\mathcal{J}$ according to the size of the corresponding coefficients:
\begin{equation*}
\mathcal{I}_k:=\{i\in\mathcal{I}:2^{-(k+1)}<x_i\leq 2^{-k}\},
\qquad
\mathcal{J}_k:=\{j\in\mathcal{J}:2^{-(k+1)}<y_j\leq 2^{-k}\}.
\end{equation*}
Note the unit-norm constraints ensure that $\mathcal{I}=\bigcup_{k=0}^\infty\mathcal{I}_k$ and $\mathcal{J}=\bigcup_{k=0}^\infty\mathcal{J}_k$.
The triangle inequality thus gives
\begin{align}
\nonumber
\bigg|\bigg\langle \sum_{i\in\mathcal{I}}x_i\varphi_i,\sum_{j\in\mathcal{J}}y_j\varphi_j \bigg\rangle\bigg|
&=\bigg|\bigg\langle \sum_{k_1=0}^\infty\sum_{i\in\mathcal{I}_{k_1}}x_i\varphi_i,\sum_{k_2=0}^\infty\sum_{j\in\mathcal{J}_{k_2}}y_j\varphi_j \bigg\rangle\bigg|\\
\label{eq.partition across sizes}
&\leq\sum_{k_1=0}^\infty\sum_{k_2=0}^\infty 2^{-(k_1+k_2)} \bigg|\bigg\langle \sum_{i\in\mathcal{I}_{k_1}}\frac{x_i}{2^{-k_1}}\varphi_i,\sum_{j\in\mathcal{J}_{k_2}}\frac{y_j}{2^{-k_2}}\varphi_j \bigg\rangle\bigg|.
\end{align}
By the definitions of $\mathcal{I}_{k_1}$ and $\mathcal{J}_{k_2}$, the coefficients of $\varphi_i$ and $\varphi_j$ in \eqref{eq.partition across sizes} all lie in $[0,1]$.
As such, we continue by applying our first bound:
\begin{align}
\nonumber
\bigg|\bigg\langle \sum_{i\in\mathcal{I}}x_i\varphi_i,\sum_{j\in\mathcal{J}}y_j\varphi_j \bigg\rangle\bigg|
&\leq\sum_{k_1=0}^\infty\sum_{k_2=0}^\infty 2^{-(k_1+k_2)} \hat\theta (|\mathcal{I}_{k_1}||\mathcal{J}_{k_2}|)^{1/2}\\
\label{eq.partition across sizes 2}
&=\hat\theta\bigg(\sum_{k=0}^\infty2^{-k}|\mathcal{I}_{k}|^{1/2}\bigg)\bigg(\sum_{k=0}^\infty2^{-k}|\mathcal{J}_{k}|^{1/2}\bigg).
\end{align}
We now observe from the definition of $\mathcal{I}_k$ that
\begin{equation*}
1
=\sum_{i\in\mathcal{I}}x_i^2
=\sum_{k=0}^\infty\sum_{i\in\mathcal{I}_k}x_i^2
>\sum_{k=0}^\infty 4^{-(k+1)}|\mathcal{I}_k|.
\end{equation*}
Thus for any positive integer $t$, the Cauchy-Schwarz inequality gives
\begin{align}
\nonumber
\sum_{k=0}^\infty 2^{-k}|\mathcal{I}_k|^{1/2}
&=\sum_{k=0}^{t-1} 2^{-k}|\mathcal{I}_k|^{1/2}+\sum_{k=t}^\infty 2^{-k}|\mathcal{I}_k|^{1/2}\\
\nonumber
&\leq t^{1/2}\bigg(\sum_{k=0}^{t-1} 4^{-k}|\mathcal{I}_k|\bigg)^{1/2}+\sum_{k=t}^\infty 2^{-k}K^{1/2}\\
\label{eq.partition across sizes 3}
&< 2(t^{1/2}+K^{1/2}2^{-t}),
\end{align}
and similarly for the $\mathcal{J}_k$'s.
For a fixed $K$, we note that \eqref{eq.partition across sizes 3} is minimized when $K^{1/2}2^{-t}=\frac{t^{-1/2}}{2\log 2}$, and so we pick $t$ to be the smallest positive integer such that $K^{1/2}2^{-t}\leq\frac{t^{-1/2}}{2\log 2}$.
With this, we continue \eqref{eq.partition across sizes 2}:
\begin{align}
\nonumber
\bigg|\bigg\langle \sum_{i\in\mathcal{I}}x_i\varphi_i,\sum_{j\in\mathcal{J}}y_j\varphi_j \bigg\rangle\bigg|
&<\hat\theta\Big(2(t^{1/2}+K^{1/2}2^{-t})\Big)^2\\
\label{eq.partition across sizes 4}
&\leq 4\hat\theta \bigg(t^{1/2}+\frac{t^{-1/2}}{2\log 2}\bigg)^2
=4\hat\theta\bigg(t+\frac{1}{\log 2}+\frac{1}{(2\log 2)^2t}\bigg).
\end{align}
From here, we claim that $t\leq\lceil\frac{\log K}{\log 2}\rceil$.
Considering the definition of $t$, this is easily verified for $K=2,3,\ldots,7$ by showing $K^{1/2}2^{-s}\leq\frac{s^{-1/2}}{2\log 2}$ for $s=\lceil\frac{\log K}{\log 2}\rceil$.
For $K\geq8$, one can use calculus to verify the second inequality of the following:
\begin{equation*}
K^{1/2}2^{-\lceil\frac{\log K}{\log 2}\rceil}
\leq K^{1/2}2^{-\frac{\log K}{\log 2}}
\leq \frac{1}{2\log 2}\bigg(\frac{\log K}{\log 2}+1\bigg)^{-1/2}
\leq \frac{1}{2\log 2}\bigg\lceil\frac{\log K}{\log 2}\bigg\rceil^{-1/2},
\end{equation*}
meaning $t\leq\lceil\frac{\log K}{\log 2}\rceil$.
Substituting $t\leq\frac{\log K}{\log 2}+1$ and $t\geq1$ into \eqref{eq.partition across sizes 4} then gives
\begin{equation*}
\bigg|\bigg\langle \sum_{i\in\mathcal{I}}x_i\varphi_i,\sum_{j\in\mathcal{J}}y_j\varphi_j \bigg\rangle\bigg|
<4\hat\theta\bigg(\frac{\log K}{\log2}+1+\frac{1}{\log 2}+\frac{1}{(2\log 2)^2}\bigg)\\
=\hat\theta(C_0\log K+C_1),
\end{equation*}
with $C_0\approx 5.77$, $C_1\approx 11.85$.
As such, \eqref{eq.to bound} is $\leq C'\hat\theta\log K$ with $C'=C_0+\frac{C_1}{\log 2}$ in this case.

We are now ready for the final bound on \eqref{eq.to bound} in which we apply no constraints on the $x_i$'s and $y_j$'s.
To do this, we consider the positive and negative real and imaginary parts of these coefficients:
\begin{equation*}
x_i=\sum_{k=0}^3x_{i,k}\mathrm{i}^k\quad \mbox{s.t.}\quad x_{i,k}\geq0\quad \forall k,
\end{equation*}
and similarly for the $y_j$'s.
With this decomposition, we apply the triangle inequality to get
\begin{align*}
\bigg|\bigg\langle \sum_{i\in\mathcal{I}}x_i\varphi_i,\sum_{j\in\mathcal{J}}y_j\varphi_j \bigg\rangle\bigg|
&=\bigg|\bigg\langle \sum_{i\in\mathcal{I}}\sum_{k_1=0}^3x_{i,k_1}\mathrm{i}^{k_1}\varphi_i,\sum_{j\in\mathcal{J}}\sum_{k_2=0}^3y_{j,k_2}\mathrm{i}^{k_2}\varphi_j \bigg\rangle\bigg|\\
&\leq\sum_{k_1=0}^3\sum_{k_2=0}^3\bigg|\bigg\langle \sum_{i\in\mathcal{I}}x_{i,k_1}\varphi_i,\sum_{j\in\mathcal{J}}y_{j,k_2}\varphi_j \bigg\rangle\bigg|.
\end{align*}
Finally, we normalize the coefficients by $(\sum_{i\in\mathcal{I}}x_{i,k_1}^2)^{1/2}$ and $(\sum_{j\in\mathcal{J}}y_{j,k_2}^2)^{1/2}$ so we can apply our second bound:
\begin{align*}
\bigg|\bigg\langle \sum_{i\in\mathcal{I}}x_i\varphi_i,\sum_{j\in\mathcal{J}}y_j\varphi_j \bigg\rangle\bigg|
&\leq\sum_{k_1=0}^3\sum_{k_2=0}^3\bigg(\sum_{i\in\mathcal{I}}x_{i,k_1}^2\bigg)^{1/2}\bigg(\sum_{j\in\mathcal{J}}y_{j,k_2}^2\bigg)^{1/2} C'\hat\theta\log K\\
&\leq(C\hat\theta\log K)\|x\|\|y\|,
\end{align*}
where $C=4C'\approx74.17$ by the Cauchy-Schwarz inequality, and so we are done.

We say an $M\times N$ unit norm frame $\Phi$ satisfies the \emph{strong coherence property} if
\begin{equation*}
\mbox{(SCP-1)}~~~\mu\leq\frac{1}{164\log N}\qquad\mbox{and}\qquad\mbox{(SCP-2)}~~~\nu\leq\frac{\mu}{\sqrt{M}},
\end{equation*}
where $\mu$ and $\nu$ are given by \eqref{eq.mu defn} and \eqref{eq.nu defn}, respectively.

\label{def:WRIP}
We say an $M\times N$ frame $\Phi$ satisfies the \emph{$(K,\delta,p)$-weak restricted isometry property (weak RIP)} if for every $K$-sparse vector $y \in \mathbb{C}^N$, a random permutation $x$ of $y$'s entries satisfies
\begin{equation}
\label{thmeqn:REP}
(1-\delta)\|x\|^2 \leq \|\Phi x\|^2 \leq (1+\delta)\|x\|^2
\end{equation}
with probability exceeding $1-p$.

\label{thm:RSP}
Take an $M\times N$ unit norm frame $\Phi$ which satisfies the strong coherence property, pick $t\in(0,1)$, and choose $\lambda = \sqrt{2\sigma^2\log{N}}\max \{\frac{10}{t}\mu\sqrt{M\textsc{snr}}, \frac{\sqrt{2}}{1-t}\}$. 
Further, suppose $x \in \mathbb{C}^N$ has support $\mathcal{K}$ drawn uniformly at random from all possible $K$-subsets of $\{1,\ldots,N\}$.
Then provided
\begin{equation}
\label{thmeqn:RSP}
K \leq \frac{N}{c_1^2\|\Phi\|_2^2\log{N}},
\end{equation}
Algorithm~\ref{alg:OST_recon} produces $\hat{\mathcal{K}}$ such that $\mathcal{T}_\sigma(t) \cap \mathcal{T}_\mu(t) \subseteq \hat{\mathcal{K}} \subseteq \mathcal{K}$ and $\hat{x}$ such that
\begin{equation}
\label{thmeqn:RSP_2}
\|x-\hat{x}\| \leq c_2 \sqrt{\sigma^2|\hat{\mathcal{K}}|\log{N}} + c_3\|x_{\mathcal{K} \setminus \hat{\mathcal{K}}}\|
\end{equation}
with probability exceeding $1 - 10N^{-1}$. Finally, defining $T:=|\mathcal{T}_\sigma(t) \cap \mathcal{T}_\mu(t)|$, we further have
\begin{equation}
\label{thmeqn:RSP_3}
\|x-\hat{x}\| \leq c_2 \sqrt{\sigma^2 K \log{N}} + c_3\|x - x_T\|
\end{equation}
in the same probability event.
Here, $c_1 = 37e$, $c_2 = \frac{2}{1-e^{-1/2}}$, and $c_3 = 1 + \frac{e^{-1/2}}{1-e^{-1/2}}$ are numerical constants.

To begin, note that since $\|\Phi\|_2^2\geq\frac{N}{M}$, we have from \eqref{thmeqn:RSP} that $K\leq M/(2\log{N})$. 
It is then easy to conclude from Theorem~5 of~\cite{bajwa:jcn10} that $\hat{\mathcal{K}}$ satisfies $\mathcal{T}_\sigma(t) \cap \mathcal{T}_\mu(t) \subseteq \hat{\mathcal{K}} \subseteq \mathcal{K}$ with probability exceeding $1 - 6N^{-1}$. Therefore, conditioned on the event $\mathcal{E}_1 := \{\mathcal{T}_\sigma(t) \cap \mathcal{T}_\mu(t) \subseteq \hat{\mathcal{K}} \subseteq \mathcal{K}\}$, we can make use of the triangle inequality to write
\begin{equation}
\label{pfeqn:RSP_1}
\|x - \hat{x}\|\leq \|x_{\hat{\mathcal{K}}} - \hat{x}_{\hat{\mathcal{K}}}\| + \|x_{\mathcal{K}\setminus\hat{\mathcal{K}}}\|.
\end{equation}
Next, we may use \eqref{thmeqn:RSP} and the fact that $\Phi$ satisfies the strong coherence property to conclude from~\cite{tropp:cras08} (see, e.g., Proposition~3 of~\cite{bajwa:jcn10}) that 
$\|\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}-I_K\|_2 < e^{-1/2}$ with probability exceeding $1 - 2N^{-1}$. 
Hence, conditioning on $\mathcal{E}_1$ and $\mathcal{E}_2 := \{\|\Phi_\mathcal{K}^*\Phi_\mathcal{K}^{}-I_K\|_2 < e^{-1/2}\}$, we have that $(\Phi_{\hat{\mathcal{K}}})^\dagger = (\Phi_{\hat{\mathcal{K}}}^* \Phi_{\hat{\mathcal{K}}}^{})^{-1} \Phi_{\hat{\mathcal{K}}}^*$ since $\Phi_{\hat{\mathcal{K}}}$ is a submatrix of a full column rank matrix $\Phi_\mathcal{K}$.
Therefore, given $\mathcal{E}_1$ and $\mathcal{E}_2$, we may write
\begin{equation}
\label{pfeqn:RSP_1.5}
\hat{x}_{\hat{\mathcal{K}}} 
= (\Phi_{\hat{\mathcal{K}}})^\dagger (\Phi x+z) 
=  x_{\hat{\mathcal{K}}} + (\Phi_{\hat{\mathcal{K}}})^\dagger \Phi_{\mathcal{K} \setminus \hat{\mathcal{K}}}x_{\mathcal{K} \setminus \hat{\mathcal{K}}} + (\Phi_{\hat{\mathcal{K}}})^\dagger z,
\end{equation}
and so substituting \eqref{pfeqn:RSP_1.5} into \eqref{pfeqn:RSP_1} and applying the triangle inequality gives
\begin{align}
\nonumber
\|x - \hat{x}\| 
&\leq \|(\Phi_{\hat{\mathcal{K}}})^\dagger \Phi_{\mathcal{K} \setminus \hat{\mathcal{K}}}x_{\mathcal{K} \setminus \hat{\mathcal{K}}}\| + \|(\Phi_{\hat{\mathcal{K}}})^\dagger z\| + \|x_{\mathcal{K} \setminus \hat{\mathcal{K}}}\|\\
\label{pfeqn:RSP_2}
&\leq \Big(1 + \|(\Phi_{\hat{\mathcal{K}}}^* \Phi_{\hat{\mathcal{K}}}^{})^{-1}\|_2 \|\Phi_{\hat{\mathcal{K}}}^* \Phi_{\mathcal{K} \setminus \hat{\mathcal{K}}}^{}\|_2\Big)\|x_{\mathcal{K} \setminus \hat{\mathcal{K}}}^{}\| + \|(\Phi_{\hat{\mathcal{K}}}^* \Phi_{\hat{\mathcal{K}}}^{})^{-1}\|_2 \|\Phi_{\hat{\mathcal{K}}}^* z\|.
\end{align}
Since, given $\mathcal{E}_1$, we have that $\Phi_{\hat{\mathcal{K}}}^* \Phi_{\hat{\mathcal{K}}}^{} - I_K$ and $\Phi_{\hat{\mathcal{K}}}^* \Phi_{\mathcal{K} \setminus \hat{\mathcal{K}}}^{}$ are submatrices of $\Phi_\mathcal{K}^* \Phi_\mathcal{K}^{} - I_K$, and since the spectral norm of a matrix provides an upper bound for the spectral norms of its submatrices, we have the following given $\mathcal{E}_1$ and $\mathcal{E}_2$:
$\|\Phi_{\hat{\mathcal{K}}}^* \Phi_{\mathcal{K} \setminus \hat{\mathcal{K}}}^{}\|_2 \leq e^{-1/2}$
and
$\|(\Phi_{\hat{\mathcal{K}}}^* \Phi_{\hat{\mathcal{K}}}^{})^{-1}\|_2 \leq \frac{1}{1-e^{-1/2}}$.
We can now substitute these bounds into \eqref{pfeqn:RSP_2} and make use of the fact that $\|\Phi_{\hat{\mathcal{K}}}^* z\| \leq |\hat{\mathcal{K}}|^{1/2}\|\Phi_{\hat{\mathcal{K}}}^* z\|_\infty$ to conclude that
\begin{equation*}
\|x - \hat{x}\| \leq \frac{|\hat{\mathcal{K}}|^{1/2}}{1-e^{-1/2}} \|\Phi_{\hat{\mathcal{K}}}^* z\|_\infty + \Big(1 + \frac{e^{-1/2}}{1-e^{-1/2}}\Big)\|x_{\mathcal{K} \setminus \hat{\mathcal{K}}}\|,
\end{equation*}
given $\mathcal{E}_1$ and $\mathcal{E}_2$. 
At this point, define the event $\mathcal{E}_3 = \{\|\Phi_{\hat{\mathcal{K}}}^* z\|_\infty \leq 2\sqrt{\sigma^2 \log{N}}\}$ and note from Lemma~6 of~\cite{bajwa:jcn10} that $\Pr(\mathcal{E}_3^\mathrm{c}) \leq 2(\sqrt{2\pi\log{N}}~N)^{-1}$. 
A union bound therefore gives \eqref{thmeqn:RSP_2} with probability exceeding $1 - 10N^{-1}$. 
For \eqref{thmeqn:RSP_3}, note that $\hat{\mathcal{K}} \subseteq \mathcal{K}$ implies $|\hat{\mathcal{K}}| \leq K$, and so $\mathcal{T}_\sigma(t) \cap \mathcal{T}_\mu(t) \subseteq \hat{\mathcal{K}}$ implies that $\|x_{\mathcal{K} \setminus \hat{\mathcal{K}}}\| \leq \|x_{\mathcal{K} \setminus (\mathcal{T}_\sigma(t) \cap \mathcal{T}_\mu(t))}\| = \|x - x_T\|$.

Let $\mathcal{K}$ be the support of $x$, and define $\mathcal{I} := \{n : |x_n| = \alpha\}$.
We wish to show that $\mathcal{I}\subseteq\mathcal{T}_\mu(t)$, since this implies $\|x_{\mathcal{K} \setminus
\mathcal{T}_\mu(t)}\| \leq \|x_{\mathcal{K} \setminus \mathcal{I}}\| =
\mathrm{O}(\sqrt{\sigma^2 K\log{N}})$.
In order to prove $\mathcal{I}\subseteq\mathcal{T}_\mu(t)$, notice that
\begin{equation*}
\|x\|^2 
= \|x_{\mathcal{I}}\|^2+\|x_{\mathcal{K}\setminus\mathcal{I}}\|^2 
< \beta K \alpha^2 + (1-\beta)K\alpha^2 
= K\alpha^2,
\end{equation*}
and so combining this with the fact that $\|\Phi\|_2^2\geq\frac{N}{M}$ gives
\begin{equation*}
\mu \|x\| \sqrt{\log{N}}
< \frac{c_0}{\sqrt{M}} \sqrt{K} \alpha \sqrt{\log{N}}
\leq \frac{c_0}{\sqrt{M}} \sqrt{\frac{N}{c_1^2\|\Phi\|_2^2\log N}} ~\alpha\sqrt{\log{N}}
\leq \frac{c_0}{c_1}\alpha.
\end{equation*}
Therefore, provided $c_0\leq\frac{tc_1}{20\sqrt{2}}$, we have that $\mathcal{I}\subseteq\mathcal{T}_\mu(t)$.

\label{lem.sufficient conditions}
For any $M\times N$ unit norm frame $\Phi$, each of the following conditions implies $\nu\leq\frac{\mu}{\sqrt{M}}$:
\begin{enumerate}
\item[(i)] $\langle \varphi_k,\sum_{n=1}^N \varphi_n\rangle=\frac{N}{M}$ for every $k=1,\ldots,N$,
\item[(ii)] $N\geq2M$ and $\sum_{n=1}^N \varphi_n=0$,
\item[(iii)] $N\geq M^2+3M+3$ and $\|\sum_{n=1}^N \varphi_n\|^2\leq N$.
\end{enumerate}

\label{thm.normalized gaussian frames}
Build a real $M\times N$ frame $\Psi$ by drawing entries independently at random from a Gaussian distribution of zero mean and unit variance.
Next, construct a normalized Gaussian frame $\Phi$ by taking $\varphi_n:=\frac{\psi_n}{\|\psi_n\|}$ for every $n=1,\ldots,N$.
Provided $60\log{N}\leq M\leq\frac{N-1}{4\log{N}}$, then the following simultaneously hold with probability exceeding $1 - 11N^{-1}$:
\begin{enumerate}
\item[(i)] $\mu \leq \frac{\sqrt{15\log{N}}}{\sqrt{M} - \sqrt{12\log{N}}}$,
\item[(ii)] $\nu \leq \frac{\sqrt{15\log{N}}}{M - \sqrt{12M\log{N}}}$,
\item[(iii)] $\|\Phi\|_2 \leq \frac{\sqrt{M} + \sqrt{N} + \sqrt{2\log{N}}}{\sqrt{M - \sqrt{8M\log{N}}}}$.
\end{enumerate}

Theorem~\ref{thm.normalized gaussian frames}(i) can be shown to hold with probability exceeding $1 - 2N^{-1}$ by using a bound on the norm of a Gaussian random vector in Lemma~1 of~\cite{LaurentM:00} and a bound on the magnitude of the inner product of two independent Gaussian random vectors in Lemma~6 of~\cite{haupt:tit10}. Specifically, pick any two distinct indices $i, j \in \{1,\dots,N\}$, and define probability events $\mathcal{E}_1 := \{|\langle \psi_i,\psi_j\rangle| \leq \varepsilon_1\}$, $\mathcal{E}_2 := \{\|\psi_i\|^2 \geq M(1 - \varepsilon_2)\}$, and $\mathcal{E}_3 := \{\|\psi_j\|^2 \geq M(1 - \varepsilon_2)\}$ for $\varepsilon_1 = \sqrt{15M\log{N}}$ and $\varepsilon_2 = \sqrt{(12\log{N})/M}$. Then it follows from the union bound that
\begin{equation*}
\Pr\bigg(|\langle \varphi_i,\varphi_j\rangle| > \frac{\varepsilon_1}{M(1-\varepsilon_2)} \bigg)
= \Pr\bigg(\frac{|\langle \psi_i,\psi_j\rangle|}{\|\psi_i\|\|\psi_j\|} > \frac{\varepsilon_1}{M(1-\varepsilon_2)} \bigg)
\leq \Pr(\mathcal{E}_1^\mathrm{c}) + \Pr(\mathcal{E}_2^\mathrm{c}) + \Pr(\mathcal{E}_3^\mathrm{c}).
\end{equation*}
One can verify that $\Pr(\mathcal{E}_2^\mathrm{c}) = \Pr(\mathcal{E}_3^\mathrm{c}) \leq N^{-3}$ because of Lemma~1 of~\cite{LaurentM:00}, and we further have $\Pr(\mathcal{E}_1^\mathrm{c}) \leq 2N^{-3}$ because of Lemma~6 of~\cite{haupt:tit10} and the fact that $M \geq 60\log{N}$. 
Thus, for any fixed $i$ and $j$, 
$|\langle \varphi_i,\varphi_j\rangle| \leq \sqrt{15\log{N}}/(\sqrt{M} - \sqrt{12\log{N}})$
with probability exceeding $1 - 4N^{-3}$. 
It therefore follows by taking a union bound over all $\binom{N}{2}$ choices for $i$ and $j$ that Theorem~\ref{thm.normalized gaussian frames}(i) holds with probability exceeding $1 - 2N^{-1}$.

Theorem~\ref{thm.normalized gaussian frames}(ii) can be shown to hold with probability exceeding $1 - 6N^{-1}$ by appealing to the preceding analysis and Hoeffding's inequality for a sum of independent, bounded random variables~\cite{hoeffding:jasa63}. Specifically, fix any index $i \in \{1,\dots,N\}$, and define random variables $Z_{ij} := \frac{1}{N-1}\langle \varphi_i, \varphi_j\rangle$. Next, define the probability event 
\begin{equation*}
\mathcal{E}_4 := \bigcap_{\substack{j=1\\j\neq i}}^N\bigg\{|Z_{ij}| \leq \frac{1}{N-1}\frac{\sqrt{15\log{N}}}{\sqrt{M} - \sqrt{12\log{N}}}\bigg\}. 
\end{equation*}
Using the analysis for the worst-case coherence of $\Phi$ and taking a union bound over the $N-1$ possible $j$'s gives $\Pr(\mathcal{E}_4^\mathrm{c}) \leq 4N^{-2}$. 
Furthermore, taking $\varepsilon_3 := \sqrt{15\log{N}}/(M - \sqrt{12M\log{N}})$, then elementary probability analysis gives
\begin{align}
\nonumber
\Pr\Bigg(\bigg|\sum_{\substack{j=1\\j \not= i}}^{N} Z_{ij}\bigg| > \varepsilon_3\Bigg) 
&\leq \Pr\Bigg(\bigg|\sum_{\substack{j=1\\j \not= i}}^{N} Z_{ij}\bigg| > \varepsilon_3 ~\Bigg|~ \mathcal{E}_4\Bigg) + \Pr(\mathcal{E}_4^\mathrm{c})\\
\label{pfeqn:gaussian_avc1}
&\leq \int_{\mathbb{S}^{M-1}} \!\!\! \Pr\Bigg(\bigg|\sum_{\substack{j=1\\j \not= i}}^{N} Z_{ij}\bigg| > \varepsilon_3 ~\Bigg|~ \mathcal{E}_4, \varphi_i=x\Bigg)~p_{\varphi_i}(x)~\mathrm{dH}^{M-1}(x) + 4N^{-2},
\end{align}
where $\mathbb{S}^{M-1}$ denotes the unit hypersphere in $\mathbb{R}^M$, $\mathrm{H}^{M-1}$ denotes the $(M-1)$-dimensional Hausdorff measure on $\mathbb{S}^{M-1}$, and $p_{\varphi_i}(x)$ denotes the probability density function for the random vector $\varphi_i$. The first thing to note here is that the random variables $\{Z_{ij}: j\not=i\}$ are bounded and jointly independent when conditioned on $\mathcal{E}_4$ and $\varphi_i$. This assertion mainly follows from Bayes' rule and the fact that $\{\varphi_j:j\not=i\}$ are jointly independent when conditioned on $\varphi_i$. The second thing to note is that $\mathbb{E}[Z_{ij}~|~\mathcal{E}_4, \varphi_i] = 0$ for every $j\neq i$. This comes from the fact that the random vectors $\{\varphi_n\}_{n=1}^N$ are independent and have a uniform distribution over $\mathbb{S}^{M-1}$, which in turn guarantees that the random variables $\{Z_{ij}: j\not=i\}$ have a symmetric distribution around zero when conditioned on $\mathcal{E}_4$ and $\varphi_i$. We can therefore make use of Hoeffding's inequality \cite{hoeffding:jasa63} to bound the probability expression inside the integral in \eqref{pfeqn:gaussian_avc1} as
\begin{equation}
\label{eq.prob sum bound}
\Pr\Bigg(\bigg|\sum_{\substack{j=1\\j \not= i}}^{N} Z_{ij}\bigg| > \varepsilon_3 ~\Bigg|~ \mathcal{E}_4, \varphi_i=x\Bigg)
\leq 2e^{-(N-1)/2M},
\end{equation}
which is bounded above by $2N^{-2}$ provided $M \leq \frac{N-1}{4\log{N}}$. We can now substitute \eqref{eq.prob sum bound} into \eqref{pfeqn:gaussian_avc1} and take the union bound over the $N$ possible choices for $i$ to conclude that Theorem~\ref{thm.normalized gaussian frames}(ii) holds with probability exceeding $1 - 6N^{-1}$.

Lastly, Theorem~\ref{thm.normalized gaussian frames}(iii) can be shown to hold with probability exceeding $1 - 3N^{-1}$ by using a bound on the spectral norm of standard Gaussian random matrices reported in~\cite{rudelson:icm10} along with Lemma~1 of~\cite{LaurentM:00}. Specifically, define an $N \times N$ diagonal matrix $D := \mathrm{diag}(\|\psi_1\|^{-1}, \dots, \|\psi_N\|^{-1})$, and note that the entries of $\Psi := \Phi D^{-1}$ are independently and normally distributed with zero mean and unit variance. We therefore have from (2.3) in \cite{rudelson:icm10} that
\begin{equation}
\label{pfeqn:gaussian_spnorm1}
    \Pr\Big(\|\Psi\|_2 > \sqrt{M} + \sqrt{N} + \sqrt{2\log{N}}\Big) \leq 2 N^{-1}.
\end{equation}
In addition, we can appeal to the preceding analysis for the probability bound on Theorem~\ref{thm.normalized gaussian frames}(i) and conclude using Lemma~1 of~\cite{LaurentM:00} and a union bound over the $N$ possible choices for $i$ that
\begin{equation}
\label{pfeqn:gaussian_spnorm2}
    \Pr\Big(\|D\|_2 > \Big(M - \sqrt{8M\log{N}}\Big)^{-1/2}\Big) \leq N^{-1}.
\end{equation}
Finally, since $\|\Phi\|_2 \leq \|\Psi\|_2 \|D\|_2$, we can take a union bound over \eqref{pfeqn:gaussian_spnorm1} and \eqref{pfeqn:gaussian_spnorm2} to argue that Theorem~\ref{thm.normalized gaussian frames}(iii) holds with probability exceeding $1 - 3N^{-1}$. 

The complete result now follows by taking a union bound over the failure probabilities for the conditions (i)-(iii) in Theorem~\ref{thm.normalized gaussian frames}.

\label{thm.chirp}
Pick $M$ prime, and let $\Phi$ be the $M\times M^2$ frame of all powers and modulates of the chirp function $h_M$.
Then $\Phi$ is a unit norm tight frame with $\|\Phi\|_2=\sqrt{M}$, and has worst case coherence $\mu=\frac{1}{\sqrt{M}}$ and average coherence $\nu\leq\frac{\mu}{\sqrt{M}}$.

\label{thm.spherical 2-designs}
Pick $M$ even and $N\geq2M$.
Take an $\frac{M}{2}\times N$ harmonic frame $\Psi$ by collecting rows from a discrete Fourier transform matrix according to a set of nonzero indices $\mathcal{M}$ and normalizing the columns.
Let $m(n)$ denote $n$th largest index in $\mathcal{M}$, and define a real $M\times N$ frame $\Phi$ by
\begin{equation*}
\Phi_{k\ell}:=\left\{ \begin{array}{ll}\sqrt{\frac{2}{M}}\cos(\frac{2\pi m((k+1)/2)\ell}{N}),&k\mbox{ odd}\\\sqrt{\frac{2}{M}}\sin(\frac{2\pi m(k/2)\ell}{N}),&k\mbox{ even}\end{array} \right., \qquad k=1,\ldots,M, ~\ell=0,\ldots,N-1.
\end{equation*}
Then $\Phi$ is unit norm and tight, i.e., $\|\Phi\|_2^2=\frac{N}{M}$, with worst-case coherence $\mu_\Phi\leq\mu_\Psi$ and average coherence $\nu\leq\frac{\mu}{\sqrt{M}}$.

\label{thm.steiner etf coherence}
Build an $M\times N$ matrix $\Phi$ according to Theorem~\ref{theorem.steiner etfs}, and in step (iii), choose rows from the (complex) Hadamard matrix $H$ that are not all-ones.
Then $\Phi$ is an equiangular tight frame, meaning $\|\Phi\|_2^2=\frac{N}{M}$ and $\mu^2=\frac{N-M}{M(N-1)}$, and has average coherence $\nu\leq\frac{\mu}{\sqrt{M}}$.

\label{thm.asymptotic bound}
Every sufficiently large $M\times N$ unit norm frame with $N\geq2M$ and worst-case coherence $\mu<\frac{1}{2}$ satisfies
\begin{equation}
\mu^2\log\frac{1}{\mu}\geq\frac{C\log N}{M}
\end{equation}
for some constant $C>0$.

\label{thm.complex bound}
Every $M\times N$ unit norm frame has worst-case coherence $\mu\geq1-2N^{-1/(M-1)}$.
Furthermore, taking $N=\Theta(a^M)$, this lower bound goes to $1-\frac{2}{a}$ as $M\rightarrow\infty$.

\label{thm.bound}
Every real $M\times N$ unit norm frame has worst-case coherence
\begin{equation}
\label{eq.my bound}
\mu\geq\cos\bigg[\pi\bigg(\frac{M-1}{N\pi^{1/2}}\cdot\frac{\Gamma(\frac{M-1}{2})}{\Gamma(\frac{M}{2})}\bigg)^{\frac{1}{M-1}}\bigg].
\end{equation}
Furthermore, taking $N=\Theta(a^M)$, this lower bound goes to $\cos(\frac{\pi}{a})$ as $M\rightarrow\infty$.

\label{def.flipping and wiggling}
We say the frames $\Phi$ and $\Psi$ are \emph{wiggling equivalent} if there exists a diagonal matrix $D$ of unimodular entries such that $\Psi=\Phi D$.
Furthermore, they are \emph{flipping equivalent} if $D$ is real, having only $\pm1$'s on the diagonal.

\label{thm:avc_rand}
Let $\Phi$ be an $M\times N$ unit norm frame with $\smash{M < \frac{N-1}{4\log 4N}}$.
Then there exists a frame $\Psi$ that is flipping equivalent to $\Phi$ and satisfies $\smash{\nu\leq\frac{\mu}{\sqrt{M}}}$.

\label{thm.alg}
Suppose $N\geq M^2+3M+3$.
Then Algorithm~\ref{alg:flipping} outputs an $M\times N$ frame $\Psi$ that is flipping equivalent to $\Phi$ and satisfies $\nu\leq\frac{\mu}{\sqrt{M}}$.
